analytics.query:
query WorkerVersionOutcomes($account: String!, $start: Time!, $end: Time!) {
  viewer {
    accounts(filter: {accountTag: $account}) {
      workersInvocationsAdaptive(limit: 100, filter: {
        scriptName: "cambium-quests", datetime_geq: $start, datetime_lt: $end
      }) {
        dimensions { scriptVersion status isPreview }
        sum { requests }
      }
    }
  }
}
